using System;using System.IO;using System.Linq;using System.Reflection;using System.Reflection.Emit;using System.Reflection.Metadata;using System.Reflection.Metadata.Ecma335;using System.Reflection.PortableExecutable;
class Program { static void Main(string[] a){using var pe=new PEReader(File.OpenRead(a[0]));var r=pe.GetMetadataReader();var ops=typeof(OpCodes).GetFields().Where(x=>x.FieldType==typeof(OpCode)).Select(x=>(OpCode)x.GetValue(null)).ToDictionary(x=>(ushort)x.Value);
foreach(var t in r.TypeDefinitions){var td=r.GetTypeDefinition(t);if(!new[]{"BMECObject","BMECObjectWriter"}.Contains(r.GetString(td.Name)))continue;
foreach(var m in td.GetMethods()){var md=r.GetMethodDefinition(m);if(!new[]{"Create","Serialize","UpdateTransform"}.Contains(r.GetString(md.Name))||md.RelativeVirtualAddress==0)continue;
Console.WriteLine(r.GetString(td.Name)+"."+r.GetString(md.Name));var il=pe.GetMethodBody(md.RelativeVirtualAddress).GetILBytes();for(int i=0;i<il.Length;){int offset=i;ushort op=il[i++];if(op==254)op=(ushort)(0xfe00|il[i++]);var code=ops[op];int n=code.OperandType switch{OperandType.InlineNone=>0,OperandType.ShortInlineBrTarget or OperandType.ShortInlineI or OperandType.ShortInlineVar=>1,OperandType.InlineVar=>2,OperandType.InlineI8 or OperandType.InlineR=>8,OperandType.InlineSwitch=>4+4*BitConverter.ToInt32(il,i),_=>4};
if(code.OperandType==OperandType.InlineMethod){var h=MetadataTokens.EntityHandle(BitConverter.ToInt32(il,i));string name=h.Kind==HandleKind.MethodDefinition?r.GetString(r.GetMethodDefinition((MethodDefinitionHandle)h).Name):h.Kind==HandleKind.MemberReference?r.GetString(r.GetMemberReference((MemberReferenceHandle)h).Name):h.Kind.ToString();Console.WriteLine(offset.ToString("X4")+" "+code.Name+" "+name);}i+=n;}}}}}